CREATE OR REPLACE VIEW "research_municipal_wages" AS SELECT DISTINCT ON (CASE WHEN NULLIF(_edge_payload->>E'רשות','') IS NOT NULL AND CASE WHEN replace(replace(btrim(_edge_payload->>E'שנה'),',',''),'%','') ~ '^-?[0-9]+([.][0-9]+)?$' THEN replace(replace(btrim(_edge_payload->>E'שנה'),',',''),'%','')::numeric ELSE NULL END IS NOT NULL THEN jsonb_build_array(NULLIF(_edge_payload->>E'רשות',''),CASE WHEN replace(replace(btrim(_edge_payload->>E'שנה'),',',''),'%','') ~ '^-?[0-9]+([.][0-9]+)?$' THEN replace(replace(btrim(_edge_payload->>E'שנה'),',',''),'%','')::numeric ELSE NULL END)::text ELSE _edge_source_key END) _edge_hash AS _record_id,_edge_loaded_at AS _loaded_at,_edge_payload AS _source_payload,NULLIF(_edge_payload->>E'רשות','') AS "municipality",CASE WHEN replace(replace(btrim(_edge_payload->>E'שנה'),',',''),'%','') ~ '^-?[0-9]+([.][0-9]+)?$' THEN replace(replace(btrim(_edge_payload->>E'שנה'),',',''),'%','')::numeric ELSE NULL END AS "observation_year",CASE WHEN replace(replace(btrim(_edge_payload->>E'שכר ממוצע'),',',''),'%','') ~ '^-?[0-9]+([.][0-9]+)?$' THEN replace(replace(btrim(_edge_payload->>E'שכר ממוצע'),',',''),'%','')::numeric ELSE NULL END AS "average_wage" FROM "over_e27374bd43454cb9b882247898a7362a" ORDER BY CASE WHEN NULLIF(_edge_payload->>E'רשות','') IS NOT NULL AND CASE WHEN replace(replace(btrim(_edge_payload->>E'שנה'),',',''),'%','') ~ '^-?[0-9]+([.][0-9]+)?$' THEN replace(replace(btrim(_edge_payload->>E'שנה'),',',''),'%','')::numeric ELSE NULL END IS NOT NULL THEN jsonb_build_array(NULLIF(_edge_payload->>E'רשות',''),CASE WHEN replace(replace(btrim(_edge_payload->>E'שנה'),',',''),'%','') ~ '^-?[0-9]+([.][0-9]+)?$' THEN replace(replace(btrim(_edge_payload->>E'שנה'),',',''),'%','')::numeric ELSE NULL END)::text ELSE _edge_source_key END,COALESCE(_edge_payload->>'first_seen',_edge_payload->>'_first_seen','') DESC,_edge_loaded_at DESC,_edge_hash DESC;
COMMENT ON VIEW "research_municipal_wages" IS E'{"grain":"municipality and year","keys":["municipality","observation_year"],"source":"https://municipal-data.org/demographics?metric=wage","caveats":["Historical observations are restricted to 2022 onward. Current geography/planning references are retained regardless of original creation year.","Raw tables retain change versions; use the semantic view for analysis.","Empty and nonnumeric values become NULL, not zero.","City-level indicators must not be assigned to individual neighborhoods without a suitable crosswalk.","Financial source units may be NIS, thousands of NIS or ratios; do not assume a unit from the field name."]}';
